.how-block h3{font-family:var(--display);font-style:italic;font-size:22px;color:var(--acid);margin:0 0 10px;letter-spacing:.03em;}
.keyrow{display:flex;align-items:center;gap:5px;margin-bottom:6px;min-height:24px;}
