.how-block.rules .fine{font-size:8px;color:rgba(244,240,230,.35);}
.howto-panel .big-btn{align-self:flex-start;}

/* ================= TOUCH ================= */
.touch{position:absolute;inset:0;z-index:15;pointer-events:none;display:flex;align-items:flex-end;justify-content:space-between;padding:0 14px calc(14px + env(safe-area-inset-bottom));}
.dpad{position:relative;width:170px;height:150px;pointer-events:none;}
.tbtn{pointer-events:auto;touch-action:none;border:2px solid rgba(255,255,255,.55);background:rgba(8,8,13,.5);color:#fff;backdrop-filter:blur(5px);display:flex;flex-direction:column;align-items:center;justify-content:center;font-family:var(--display);font-style:italic;user-select:none;transition:background .08s,transform .08s;}
.tbtn:active,.tbtn.pressed{background:var(--acid);color:var(--ink);transform:scale(.94);border-color:var(--ink);}
.dp{position:absolute;width:58px;height:58px;font-size:20px;}
.dp.up{left:56px;top:0;border-radius:12px 12px 4px 4px;}
.dp.left{left:0;top:58px;border-radius:12px 4px 4px 12px;}
.dp.right{left:112px;top:58px;border-radius:4px 12px 12px 4px;}
.dp.block{left:56px;top:58px;font-size:17px;border-radius:4px;}
.touch-actions{display:grid;grid-template-columns:repeat(2,64px);grid-template-rows:repeat(2,64px);gap:9px;pointer-events:none;transform:rotate(-6deg);}
.act{width:64px;height:64px;border-radius:50%;font-size:24px;line-height:1;}
