.act.super{background:rgba(139,92,255,.22);border-color:var(--violet);}
.act.super.ready{box-shadow:0 0 18px 5px rgba(233,255,53,.7);animation:superGlow .5s infinite alternate;}

/* ================= CORNER TOOLS ================= */
.corner-tools{position:absolute;right:10px;top:104px;z-index:30;display:flex;flex-direction:column;gap:5px;}
