  G.projectiles.length = 0; G.hazards.length = 0; G.particles.length = 0; G.rings.length = 0; G.slashes.length = 0; G.floaters.length = 0;
  G.hitstop = 0; G.slowT = 0; G.shake = 0; G.flash = 0; G.superFlash = 0; G.blackout = 0;
