    G.roundT += dt;
    for (const f of fighters) updateFighter(f, raw, true);
    updateHazards(raw);
    if (G.roundT > 1.25) concludeRound('TIME UP');
  } else if (G.roundState === 'concluded') {
    G.concludeT += dt;
    for (const f of fighters) updateFighter(f, raw, true);
    updateHazards(raw);
    if (G.concludeT > 2.15) {
      if (G.matchWinner >= 0) showResults();
      else { G.round++; startRound(true); }
    }
  }
