  const markers = ['#e9ff35', '#ff2e7a'];
  G.players.forEach((f, i) => {
    drawFighter(ctx, f, t, { marker: markers[i], label: i === 0 ? 'P1' : (G.mode === 'cpu' ? 'CPU' : 'P2') });
