import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
const errors = [];
page.on('pageerror', e => errors.push('PAGE: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
await page.waitForTimeout(600);

async function pickStage(stage) {
  await page.evaluate(() => showScreen('title'));
  await page.getByRole('button', { name: /VS CPU/ }).click();
  await page.waitForTimeout(300);
  await page.getByRole('button', { name: /MODI/ }).click();
  await page.getByRole('button', { name: /TRUMP/ }).click();
  await page.getByRole('button', { name: /ENTER THE ARENA/ }).click();
  await page.waitForTimeout(200);
  await page.locator('.stage-card.' + stage).click();
  await page.waitForTimeout(300);
  await page.getByRole('button', { name: /CLICK TO SKIP|SKIP/ }).click().catch(() => {});
  await page.evaluate(() => { G.vsT = 99; beginFight(); G.roundState = 'fight'; });
  await page.waitForTimeout(200);
}

for (const stage of ['desert', 'snow', 'india']) {
  await pickStage(stage);
  const state = await page.evaluate(() => ({ stage: G.stage, tag: document.querySelector('#stageTag').textContent, screen: G.screen, names: G.players.map(p => p.char.name) }));
  console.log(stage, JSON.stringify(state));
  await page.screenshot({ path: `/tmp/opencode/v-${stage}.png` });
}

// super test on india
await pickStage('india');
await page.evaluate(() => {
  const [a, b] = G.players;
  a.x = 420; b.x = 760; a.facing = 1; b.facing = -1;
  a.meter = 100; a.state = 'idle'; a.attack = null; G.roundState = 'fight';
});
await page.evaluate(() => startMove(G.players[0], 'super'));
await page.waitForTimeout(1400);
const superState = await page.evaluate(() => ({ xs: G.players.map(p => Math.round(p.x)), states: G.players.map(p => p.state), hp: G.players.map(p => Math.round(p.hp)) }));
console.log('super state', JSON.stringify(superState));
await page.screenshot({ path: '/tmp/opencode/v-super.png' });

// AI soak test 8 seconds, check no errors and CPU acts
await page.evaluate(() => { G.roundState = 'fight'; G.timer = 60; });
await page.waitForTimeout(8000);
const soak = await page.evaluate(() => ({ screen: G.screen, roundState: G.roundState, xs: G.players.map(p => Math.round(p.x)), hp: G.players.map(p => Math.round(p.hp)), timer: Math.round(G.timer) }));
console.log('soak', JSON.stringify(soak));
await page.screenshot({ path: '/tmp/opencode/v-soak.png' });

console.log('errors', JSON.stringify(errors.slice(0, 12)));
await browser.close();

