import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
const errors = [];
page.on('pageerror', e => errors.push('PAGE: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
await page.waitForTimeout(800);
await page.screenshot({ path: '/tmp/opencode/f-title.png' });
await page.getByRole('button', { name: /VS CPU/ }).click();
await page.waitForTimeout(500);
await page.screenshot({ path: '/tmp/opencode/f-select.png' });
// click through each roster card and capture any rendering errors
const cards = await page.locator('.roster .card').count();
console.log('roster cards', cards);
for (let i = 0; i < cards; i++) {
  await page.locator('.roster .card').nth(i).click();
  await page.waitForTimeout(120);
}
await page.screenshot({ path: '/tmp/opencode/f-select-last.png' });
// make a valid pick
await page.locator('.roster .card').nth(0).click();
await page.locator('.roster .card').nth(4).click();
await page.getByRole('button', { name: /ENTER THE ARENA/ }).click();
await page.waitForTimeout(400);
await page.screenshot({ path: '/tmp/opencode/f-stage.png' });
await page.locator('.stage-card.snow').click();
await page.waitForTimeout(1200);
await page.screenshot({ path: '/tmp/opencode/f-vs.png' });
await page.waitForTimeout(3000);
const st = await page.evaluate(() => ({ screen: G.screen, roundState: G.roundState }));
console.log('after vs', JSON.stringify(st));
// force finish match: p2 hp low, deliver KO
await page.evaluate(() => {
  G.vsT = 99; beginFight(); G.roundState = 'fight';
  G.players[1].hp = 1;
  G.players[0].x = G.players[1].x - 100;
  G.players[0].facing = 1; G.players[0].state = 'idle'; G.players[0].attack = null;
  hitFighter(G.players[0], G.players[1], 5, { hitstop: 1 });
});
await page.waitForTimeout(3400);
console.log('after KO', JSON.stringify(await page.evaluate(() => ({ screen: G.screen, roundState: G.roundState, wins: G.wins }))));
await page.screenshot({ path: '/tmp/opencode/f-roundwin.png' });
// second round
await page.evaluate(() => { if (G.screen === 'fight') { G.players[1].hp = 1; hitFighter(G.players[0], G.players[1], 5, { hitstop: 1 }); } });
await page.waitForTimeout(3400);
console.log('after R2', JSON.stringify(await page.evaluate(() => ({ screen: G.screen, roundState: G.roundState, wins: G.wins, matchWinner: G.matchWinner }))));
await page.screenshot({ path: '/tmp/opencode/f-results.png' });
// mobile title
const mobile = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true });
await mobile.goto('http://localhost:3002', { waitUntil: 'networkidle' });
await mobile.waitForTimeout(700);
await mobile.screenshot({ path: '/tmp/opencode/f-mobile.png' });
console.log('errors', JSON.stringify(errors.slice(0, 12)));
await browser.close();

