import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true });

async function desktop() {
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
  await page.waitForTimeout(500);
  // howto
  await page.getByRole('button', { name: /HOW TO PLAY/ }).click();
  await page.waitForTimeout(400);
  await page.screenshot({ path: '/tmp/opencode/g-howto.png' });
  await page.getByRole('button', { name: /BACK TO TITLE|TITLE/ }).first().click().catch(() => page.evaluate(() => showScreen('title')));
  await page.waitForTimeout(300);
  // local 2p flow
  await page.getByRole('button', { name: /LOCAL 2P/ }).click();
  await page.waitForTimeout(300);
  await page.locator('.roster .card').nth(1).click();
  await page.locator('.roster .card').nth(2).click();
  await page.getByRole('button', { name: /ENTER THE ARENA/ }).click();
  await page.waitForTimeout(200);
  await page.locator('.stage-card.desert').click();
  await page.waitForTimeout(300);
  await page.evaluate(() => { G.vsT = 99; beginFight(); G.roundState = 'fight'; });
  await page.waitForTimeout(300);
  // pause
  await page.evaluate(() => togglePause());
  await page.waitForTimeout(300);
  await page.screenshot({ path: '/tmp/opencode/g-pause.png' });
  await page.evaluate(() => togglePause());
  // results preview
  await page.evaluate(() => {
    G.wins = [2, 0]; G.matchWinner = 0; G.players[0].wins = 2;
    showResults();
  });
  await page.waitForTimeout(500);
  await page.screenshot({ path: '/tmp/opencode/g-results.png' });
  await page.close();
}

async function mobile() {
  const page = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 });
  await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
  await page.waitForTimeout(600);
  await page.getByRole('button', { name: /VS CPU/ }).click();
  await page.waitForTimeout(400);
  await page.screenshot({ path: '/tmp/opencode/g-m-select.png' });
  await page.locator('.roster .card').nth(0).click();
  await page.locator('.roster .card').nth(4).click();
  await page.getByRole('button', { name: /ENTER THE ARENA/ }).click();
  await page.waitForTimeout(300);
  await page.screenshot({ path: '/tmp/opencode/g-m-stage.png' });
  await page.locator('.stage-card.india').click();
  await page.waitForTimeout(400);
  await page.evaluate(() => { G.vsT = 99; beginFight(); G.roundState = 'fight'; });
  await page.waitForTimeout(500);
  await page.screenshot({ path: '/tmp/opencode/g-m-fight.png' });
  console.log('mobile touch', await page.evaluate(() => ({ isTouch, touch: document.querySelector('#touch')?.className, canvas: document.querySelector('#game').getBoundingClientRect().toJSON() })));
  await page.close();
}

await desktop();
await mobile();
await browser.close();

