import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true });
const errors = [];
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
page.on('pageerror', e => errors.push('PAGE: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
await page.waitForTimeout(700);
await page.screenshot({ path: '/tmp/opencode/h-title.png' });
console.log('app screen', await page.evaluate(() => document.getElementById('app').dataset.screen));
// select + fight to HUD
await page.getByRole('button', { name: /VS CPU/ }).click();
await page.waitForTimeout(400);
await page.screenshot({ path: '/tmp/opencode/h-select.png' });
await page.locator('.roster .card').nth(0).click();
await page.locator('.roster .card').nth(4).click();
await page.getByRole('button', { name: /ENTER THE ARENA/ }).click();
await page.waitForTimeout(300);
await page.locator('.stage-card.snow').click();
await page.waitForTimeout(300);
await page.evaluate(() => { G.vsT = 99; beginFight(); G.roundState = 'fight'; G.roundT = 99; });
await page.waitForTimeout(600);
await page.screenshot({ path: '/tmp/opencode/h-fight.png' });
await page.evaluate(() => { const [a, b] = G.players; a.x = 460; b.x = 620; a.facing = 1; b.facing = -1; a.hp = 1000; b.hp = 1000; G.roundState = 'fight'; G.timer = 58; });
await page.waitForTimeout(300);
await page.screenshot({ path: '/tmp/opencode/h-close.png' });

const mobile = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true });
await mobile.goto('http://localhost:3002', { waitUntil: 'networkidle' });
await mobile.waitForTimeout(700);
await mobile.screenshot({ path: '/tmp/opencode/h-m-title.png' });
await mobile.getByRole('button', { name: /VS CPU/ }).click();
await mobile.waitForTimeout(500);
await mobile.screenshot({ path: '/tmp/opencode/h-m-select.png' });
await mobile.locator('.roster .card').nth(0).click();
await mobile.locator('.roster .card').nth(4).click();
await mobile.getByRole('button', { name: /ENTER THE ARENA/ }).click();
await mobile.waitForTimeout(300);
await mobile.locator('.stage-card.india').click();
await mobile.waitForTimeout(300);
await mobile.evaluate(() => { G.vsT = 99; beginFight(); G.roundState = 'fight'; });
await mobile.waitForTimeout(500);
await mobile.screenshot({ path: '/tmp/opencode/h-m-fight.png' });
console.log('mobile', JSON.stringify(await mobile.evaluate(() => {
  const sb = document.querySelector('.act.act-super');
  const acts = [...document.querySelectorAll('.act')].map(e => e.getBoundingClientRect().toJSON());
  return { superRect: sb.getBoundingClientRect().toJSON(), acts, hudBottom: document.querySelector('.hud-bottom').getBoundingClientRect().toJSON(), screen: document.getElementById('app').dataset.screen };
})));
console.log('errors', JSON.stringify(errors));
await browser.close();

