input.content:
import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
const errors = [];
page.on('pageerror', e => errors.push('PAGE: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
await page.waitForTimeout(400);

// Every character: render, special, super
const report = await page.evaluate(async () => {
  const out = [];
  for (const ch of CHARS) {
    try {
      G.mode = 'local';
      G.sel = { p1: ch.id, p2: CHARS.find(c => c.id !== ch.id).id, active: 0 };
      prepareMatch('india');
      G.vsT = 99; beginFight(); G.roundState = 'fight'; G.hitstop = 0;
      const a = G.players[0], b = G.players[1];
      a.x = 500; b.x = 780; a.facing = 1; b.facing = -1;
      a.state = 'idle'; a.attack = null; a.cooldown = 0; a.meter = 100;
      const okSpecial = startMove(a, 'special');
      a.attackT = 25; updateAttack(a, 1);
      const okSuper = startMove(a, 'super');
      a.attackT = 80; updateAttack(a, 1);
      render(1);
      out.push({ id: ch.id, okSpecial, okSuper, projectiles: G.projectiles.length, hazards: G.hazards.length });
    } catch (err) { out.push({ id: ch.id, error: String(err) }); }
  }
  return out;
});
console.log(JSON.stringify(report, null, 1));

// Match completion flow
await page.evaluate(() => {
  G.mode = 'cpu';
  G.sel = { p1: 'modi', p2: 'trump', active: 0 };
  prepareMatch('desert');
  G.vsT = 99; beginFight(); G.roundState = 'fight';
});
await page.waitForTimeout(150);
await page.evaluate(() => {
  const [a, b] = G.players;
  b.hp = 1; a.x = b.x - 100; a.facing = 1;
  hitFighter(a, b, 10, { hitstop: 1, kb: 1 });
  G.roundT = 3;
});
await page.waitForTimeout(200);
let s = await page.evaluate(() => ({ roundState: G.roundState, wins: G.wins, round: G.round, winner: G.matchWinner }));
console.log('after KO', JSON.stringify(s));
// force conclude if still ko
await page.evaluate(() => { if (G.roundState === 'ko') { G.roundT = 3; } });
await page.waitForTimeout(300);
s = await page.evaluate(() => ({ roundState: G.roundState, wins: G.wins, round: G.round, winner: G.matchWinner, concludeT: G.concludeT }));
console.log('after conclude', JSON.stringify(s));
await page.evaluate(() => { G.concludeT = 3; });
await page.waitForTimeout(300);
s = await page.evaluate(() => ({ roundState: G.roundState, wins: G.wins, round: G.round, winner: G.matchWinner, screen: G.screen }));
console.log('round 2', JSON.stringify(s));
await page.evaluate(() => {
  const [a, b] = G.players;
  b.hp = 1; a.x = b.x - 100; a.facing = 1;
  hitFighter(a, b, 10, { hitstop: 1, kb: 1 });
  G.roundT = 3;
});
await page.waitForTimeout(200);
await page.evaluate(() => { if (G.roundState === 'ko') G.roundT = 3; });
await page.waitForTimeout(300);
await page.evaluate(() => { G.concludeT = 3; });
await page.waitForTimeout(300);
s = await page.evaluate(() => ({ roundState: G.roundState, wins: G.wins, round: G.round, winner: G.matchWinner, screen: G.screen }));
console.log('after round 2', JSON.stringify(s));
await page.screenshot({ path: '/tmp/opencode/j-results.png' });
console.log('errors', JSON.stringify(errors.slice(0, 10)));
await browser.close();

