const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true });
const errors = [];

// Desktop screens
const d = await browser.newPage({ viewport: { width: 1280, height: 720 } });
d.on('pageerror', e => errors.push('D ' + e.message));
await d.goto('http://localhost:3002', { waitUntil: 'networkidle' });
await d.waitForTimeout(500);
await d.getByRole('button', { name: /HOW TO PLAY/ }).click();
await d.waitForTimeout(350);
await d.screenshot({ path: '/tmp/opencode/n-howto.png' });
await d.evaluate(() => showScreen('title')); await d.waitForTimeout(200);
await d.getByRole('button', { name: /VS CPU/ }).click(); await d.waitForTimeout(300);
await d.screenshot({ path: '/tmp/opencode/n-select.png' });
await d.locator('.roster .card').nth(0).click(); await d.locator('.roster .card').nth(4).click();
await d.getByRole('button', { name: /ENTER THE ARENA/ }).click(); await d.waitForTimeout(250);
await d.screenshot({ path: '/tmp/opencode/n-stage.png' });
await d.locator('.stage-card.snow').click(); await d.waitForTimeout(250);
await d.screenshot({ path: '/tmp/opencode/n-vs.png' });
await d.evaluate(() => { G.vsT = 99; beginFight(); G.roundState = 'fight'; G.timer = 37; });
await d.waitForTimeout(400);
await d.evaluate(() => { G.wins = [2, 0]; G.matchWinner = 0; showResults(); });
await d.waitForTimeout(200);
await d.screenshot({ path: '/tmp/opencode/n-results.png' });

// Mobile title footer + select + results
