console.log('mobile disclaimer', JSON.stringify(foot));
await m.getByRole('button', { name: /VS CPU/ }).click(); await m.waitForTimeout(300);
await m.locator('.roster .card').nth(0).click(); await m.locator('.roster .card').nth(4).click();
await m.getByRole('button', { name: /ENTER THE ARENA/ }).click(); await m.waitForTimeout(200);
await m.locator('.stage-card.desert').click(); await m.waitForTimeout(200);
await m.evaluate(() => { G.vsT = 99; beginFight(); G.roundState = 'fight'; G.wins = [2, 0]; G.matchWinner = 0; showResults(); });
await m.waitForTimeout(300);
await m.screenshot({ path: '/tmp/opencode/n-m-results.png' });
console.log('errors', JSON.stringify(errors));
await browser.close();

