import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true });
const URL = 'http://localhost:3002';

async function run(name, viewport, opts = {}) {
  const page = await browser.newPage({ viewport, ...opts });
  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  page.on('pageerror', e => errors.push(String(e)));
  await page.goto(URL, { waitUntil: 'networkidle' });
  await page.waitForTimeout(700);

  const info = {};
  info.titleVisible = await page.locator('#title').isVisible();
  await page.screenshot({ path: `/tmp/opencode/z-${name}-title.png` });

  // CPU flow
  await page.getByRole('button', { name: /VS CPU/ }).click();
  await page.waitForTimeout(400);
  const roster = await page.locator('.roster .card').count();
  info.roster = roster;
  const selOverflow = await page.evaluate(() => {
    const d = document.documentElement;
    const sl = document.querySelector('.select-screen');
    const r = sl.getBoundingClientRect();
    return { docW: d.scrollWidth, winW: innerWidth, docH: d.scrollHeight, winH: innerHeight,
      selectBottom: Math.round(r.bottom), selectTop: Math.round(r.top) };
  });
  info.selOverflow = selOverflow;
  await page.screenshot({ path: `/tmp/opencode/z-${name}-select.png` });

  await page.locator('.roster .card').nth(0).click();
  await page.locator('.roster .card').nth(4).click();
  await page.getByRole('button', { name: /ENTER THE ARENA/ }).click();
  await page.waitForTimeout(350);
  const stages = await page.locator('.stage-card').count();
  info.stages = stages;
  const stageOverflow = await page.evaluate(() => ({
    docW: document.documentElement.scrollWidth, winW: innerWidth,
    docH: document.documentElement.scrollHeight, winH: innerHeight }));
  info.stageOverflow = stageOverflow;
  await page.screenshot({ path: `/tmp/opencode/z-${name}-stage.png` });

  await page.locator('.stage-card.snow').click();
  await page.waitForTimeout(300);
  info.vsVisible = await page.locator('#vsScreen').isVisible();
  await page.evaluate(() => { G.vsT = 99; beginFight(); G.roundState = 'fight'; });
  await page.waitForTimeout(700);
  info.fightActive = await page.evaluate(() => G.screen === 'fight');
  info.touchVisible = await page.locator('#touch').isVisible();
  info.superText = await page.locator('.act.act-super span').textContent().catch(() => null);

  if (opts.hasTouch) {
    // fire special and super buttons
    await page.locator('[data-touch="special"]').tap();
    await page.waitForTimeout(150);
    await page.locator('[data-touch="super"]').tap();
    await page.waitForTimeout(300);
    info.superUsed = await page.evaluate(() => ({
      meter: G.players[0].meter, superTimer: G.players[0].superTimer ?? null,
      screen: G.screen
    }));
  }
  await page.screenshot({ path: `/tmp/opencode/z-${name}-fight.png` });

  // pause via corner button
  await page.locator('#pauseBtn').click();
  await page.waitForTimeout(300);
  info.paused = await page.evaluate(() => G.paused === true && G.screen === 'pause');
  await page.screenshot({ path: `/tmp/opencode/z-${name}-pause.png` });
  await page.locator('#resumeBtn').click();
  await page.waitForTimeout(300);
  info.resumed = await page.evaluate(() => G.paused === false && G.screen === 'fight');

  // results
  await page.evaluate(() => { G.wins = [2, 0]; G.matchWinner = 0; showResults(); });
  await page.waitForTimeout(400);
  info.results = await page.evaluate(() => G.screen === 'results');
  await page.screenshot({ path: `/tmp/opencode/z-${name}-results.png` });

  info.errors = errors;
  console.log(name, JSON.stringify(info));
  await page.close();
}

await run('desktop', { width: 1280, height: 720 });
await run('portrait', { width: 390, height: 844 }, { isMobile: true, hasTouch: true, deviceScaleFactor: 2 });
await run('landscape', { width: 844, height: 390 }, { isMobile: true, hasTouch: true, deviceScaleFactor: 2 });
await browser.close();

