const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 844, height: 390 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 });
await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
await page.waitForTimeout(500);
console.log(await page.evaluate(() => {
  const r = el => { const b = el.getBoundingClientRect(); return { x: b.x, y: b.y, w: b.width, h: b.height }; };
  return {
    win: { w: innerWidth, h: innerHeight, dpr: devicePixelRatio },
    doc: { cw: document.documentElement.clientWidth, sw: document.documentElement.scrollWidth, ch: document.documentElement.clientHeight, sh: document.documentElement.scrollHeight },
    body: { cw: document.body.clientWidth, sw: document.body.scrollWidth },
    app: r(document.querySelector('#app')),
    canvas: r(document.querySelector('#game')),
    hud: r(document.querySelector('#hud')),
    title: r(document.querySelector('#title')),
    canvasAttr: { w: document.querySelector('#game').width, h: document.querySelector('#game').height },
    viewport: visualViewport ? { w: visualViewport.width, h: visualViewport.height, scale: visualViewport.scale } : null
  };
}));
await browser.close();

import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true });
const URL = 'http://localhost:3002';

async function startFight(page) {
  await page.goto(URL, { waitUntil: 'networkidle' });
  await page.waitForTimeout(500);
  await page.getByRole('button', { name: /VS CPU/ }).click();
  await page.waitForTimeout(350);
  await page.locator('.roster .card').nth(0).click();
  await page.locator('.roster .card').nth(4).click();
  await page.getByRole('button', { name: /ENTER THE ARENA/ }).click();
  await page.waitForTimeout(250);
  await page.locator('.stage-card.desert').click();
  await page.waitForTimeout(250);
  await page.evaluate(() => { G.vsT = 99; beginFight(); G.roundState = 'fight'; });
  await page.waitForTimeout(500);
}

// mobile super + pause
{
  const page = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 });
  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  page.on('pageerror', e => errors.push(String(e)));
  await startFight(page);
  const before = await page.evaluate(() => ({ meter: G.players[0].meter, supers: G.stats.supers }));
  await page.evaluate(() => { G.players[0].meter = 100; });
  await page.locator('[data-touch="super"]').tap();
  await page.waitForTimeout(250);
  const during = await page.evaluate(() => ({
    meter: G.players[0].meter, supers: G.stats.supers,
    attack: G.players[0].attack?.kind || null, state: G.players[0].state,
    superBtnReady: document.querySelector('[data-touch="super"]').classList.contains('ready'),
    superFlash: G.superFlash
  }));
  await page.waitForTimeout(500);
  await page.locator('#pauseBtn').tap();
  await page.waitForTimeout(300);
  const paused = await page.evaluate(() => ({
    paused: G.paused, pauseVisible: !document.querySelector('#pause').classList.contains('hidden'),
    touchHidden: document.querySelector('#touch').classList.contains('hidden'),
    resumeVisible: !!document.querySelector('#resumeBtn').offsetParent
  }));
  await page.screenshot({ path: '/tmp/opencode/z-final-portrait-pause.png' });
  await page.locator('#resumeBtn').tap();
  await page.waitForTimeout(250);
  const resumed = await page.evaluate(() => ({ paused: G.paused, touchVisible: !document.querySelector('#touch').classList.contains('hidden') }));
  console.log('MOBILE', JSON.stringify({ before, during, paused, resumed, errors }));
  await page.close();
}

// desktop keyboard + pause
{
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  page.on('pageerror', e => errors.push(String(e)));
  await startFight(page);
  await page.evaluate(() => { G.players[0].meter = 100; });
  await page.keyboard.press('KeyJ');
  await page.waitForTimeout(200);
  const superState = await page.evaluate(() => ({ attack: G.players[0].attack?.kind || null, supers: G.stats.supers, meter: G.players[0].meter }));
  const hpBefore = await page.evaluate(() => G.players[1].hp);
  await page.keyboard.press('KeyF');
  await page.waitForTimeout(600);
  const hpAfter = await page.evaluate(() => G.players[1].hp);
  await page.keyboard.press('Escape');
  await page.waitForTimeout(250);
  const paused = await page.evaluate(() => ({ paused: G.paused, visible: !document.querySelector('#pause').classList.contains('hidden') }));
  await page.keyboard.press('Escape');
  await page.waitForTimeout(200);
  const resumed = await page.evaluate(() => G.paused === false);
  console.log('DESKTOP', JSON.stringify({ superState, hpBefore, hpAfter, paused, resumed, errors }));
  await page.close();
}

await browser.close();

