import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true });
const URL = 'http://localhost:3002';

async function run(name, viewport, touch) {
  const page = await browser.newPage({ viewport, isMobile: touch, hasTouch: touch, deviceScaleFactor: touch ? 2 : 1 });
  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  page.on('pageerror', e => errors.push(String(e)));
  await page.goto(URL, { waitUntil: 'networkidle' });
  await page.waitForTimeout(600);

  const out = { name };
  out.title = await page.locator('#title').isVisible();
  await page.getByRole('button', { name: /VS CPU/ }).click();
  await page.waitForTimeout(350);
  out.roster = await page.locator('.roster .card').count();
  out.fit = await page.evaluate(() => {
    const w = document.querySelector('.roster-wrap');
    return { ok: w.scrollHeight <= w.clientHeight + 1, h: w.clientHeight, sh: w.scrollHeight };
  });
  out.names = await page.locator('.roster .card .cname span:first-child').allTextContents();

  await page.locator('.roster .card').nth(0).click();
  await page.locator('.roster .card').nth(4).click();
  out.p1 = await page.locator('#slot1Name').textContent().catch(() => null);
  out.p2 = await page.locator('#slot2Name').textContent().catch(() => null);
  await page.getByRole('button', { name: /ENTER THE ARENA/ }).click();
  await page.waitForTimeout(350);
  out.stages = await page.locator('.stage-card').count();
  out.stageFit = await page.evaluate(() => ({ w: innerWidth, h: innerHeight, sw: document.documentElement.scrollWidth, sh: document.documentElement.scrollHeight }));
  await page.locator('.stage-card.india').click();
  await page.waitForTimeout(300);
  out.vs = await page.locator('#vsScreen').isVisible();
  await page.evaluate(() => { G.vsT = 99; beginFight(); G.roundState = 'fight'; });
  await page.waitForTimeout(500);
  out.fight = await page.evaluate(() => G.screen === 'fight' && G.round === 1);
  out.stage = await page.evaluate(() => G.stage);

  if (touch) {
    out.touchControls = await page.locator('#touch').isVisible();
    await page.evaluate(() => { G.players[0].meter = 100; });
    await page.locator('[data-touch="super"]').tap();
    await page.waitForTimeout(250);
    out.super = await page.evaluate(() => ({ meter: G.players[0].meter, supers: G.stats.supers, attack: G.players[0].attack?.kind }));
    await page.locator('#pauseBtn').tap();
    await page.waitForTimeout(300);
    out.paused = await page.evaluate(() => G.paused && !document.querySelector('#pause').classList.contains('hidden') && document.querySelector('#touch').classList.contains('hidden'));
    await page.screenshot({ path: `/tmp/opencode/final-${name}-pause.png` });
    await page.locator('#resumeBtn').tap();
    out.resumed = await page.evaluate(() => !G.paused && !document.querySelector('#touch').classList.contains('hidden'));
  } else {
    await page.evaluate(() => { G.players[0].meter = 100; });
    await page.keyboard.press('KeyJ');
    await page.waitForTimeout(200);
    out.super = await page.evaluate(() => ({ meter: G.players[0].meter, supers: G.stats.supers, attack: G.players[0].attack?.kind }));
    await page.keyboard.press('Escape');
    await page.waitForTimeout(250);
    out.paused = await page.evaluate(() => G.paused && !document.querySelector('#pause').classList.contains('hidden'));
    await page.keyboard.press('Escape');
    out.resumed = await page.evaluate(() => !G.paused);
  }

  await page.evaluate(() => { G.wins = [2, 0]; G.matchWinner = 0; showResults(); });
  await page.waitForTimeout(450);
  out.results = await page.evaluate(() => G.screen === 'results' && !document.querySelector('#results').classList.contains('hidden'));
  await page.screenshot({ path: `/tmp/opencode/final-${name}-results.png` });
  await page.evaluate(() => showScreen('title'));
  await page.waitForTimeout(300);
  await page.screenshot({ path: `/tmp/opencode/final-${name}-title.png` });
  out.errors = errors;
  console.log(JSON.stringify(out));
  await page.close();
}

await run('desktop', { width: 1280, height: 720 }, false);
await run('portrait', { width: 390, height: 844 }, true);
await run('landscape', { width: 844, height: 390 }, true);
await run('small-landscape', { width: 568, height: 320 }, true);
await browser.close();

