files.patch:
Index: style.css
===================================================================
--- style.css
+++ style.css
@@ -109,9 +109,9 @@
 .slot.p2 .slot-info span{color:var(--hot);}
 .slot-tag{position:absolute;top:-9px;left:10px;background:var(--ink);border:1px solid currentColor;color:var(--acid);font-family:var(--mono);font-size:8px;font-weight:700;letter-spacing:.14em;padding:2px 6px;transform:skewX(5deg);}
 .slot.p2 .slot-tag{color:var(--hot);}
 .vs-mark{font-family:var(--display);font-style:italic;font-size:34px;color:var(--paper);-webkit-text-stroke:1px var(--ink);text-shadow:3px 3px 0 var(--hot);transform:rotate(-7deg);flex:none;}
-.roster-wrap{flex:1;display:flex;align-items:center;justify-content:center;min-height:0;width:100%;padding:6px 0;overflow:auto;}
+.roster-wrap{flex:1;display:flex;align-items:center;justify-content:center;min-height:0;width:100%;padding:2px 0;overflow:auto;}
 .roster{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:clamp(6px,.9vw,11px);width:1120px;max-width:100%;margin:auto;padding:2px;}
 .card{position:relative;background:#101018;border:2px solid rgba(244,240,230,.18);padding:0;overflow:hidden;transition:transform .14s,border-color .14s,box-shadow .14s;aspect-ratio:.82;text-align:left;transform:skewX(-3deg);}
 .card canvas{width:100%;display:block;background:#161620;aspect-ratio:1.02;}
 .card:hover,.card:focus-visible{transform:skewX(-3deg) translateY(-5px);border-color:var(--paper);z-index:2;}

