import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 568, height: 320 }, isMobile: true, hasTouch: true, deviceScaleFactor: 1 });
const errors = [];
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
page.on('pageerror', e => errors.push(String(e)));
await page.goto('http://localhost:3002', { waitUntil: 'domcontentloaded' });
await page.getByRole('button', { name: /VS CPU/ }).click();
await page.waitForTimeout(200);
const roster = await page.locator('.roster .card').count();
const fit = await page.evaluate(() => { const w=document.querySelector('.roster-wrap'); return {ok:w.scrollHeight<=w.clientHeight+1,h:w.clientHeight,sh:w.scrollHeight}; });
await page.locator('.roster .card').nth(0).click();
await page.locator('.roster .card').nth(4).click();
await page.getByRole('button', { name: /ENTER THE ARENA/ }).click();
await page.locator('.stage-card.india').click();
await page.evaluate(() => { G.vsT=99; beginFight(); G.roundState='fight'; });
await page.waitForTimeout(200);
const fight = await page.evaluate(() => G.screen === 'fight' && G.round === 1);
await page.evaluate(() => { G.players[0].meter=100; });
await page.locator('[data-touch="super"]').tap();
await page.waitForTimeout(100);
const superState = await page.evaluate(() => ({meter:G.players[0].meter,supers:G.stats.supers}));
await page.locator('#pauseBtn').tap();
await page.waitForTimeout(100);
const paused = await page.evaluate(() => G.paused && !document.querySelector('#pause').classList.contains('hidden'));
await page.locator('#resumeBtn').tap();
await page.evaluate(() => { G.wins=[2,0]; G.matchWinner=0; showResults(); });
const results = await page.evaluate(() => G.screen === 'results' && !document.querySelector('#results').classList.contains('hidden'));
await page.screenshot({path:'/tmp/opencode/latest-small-landscape.jpg',type:'jpeg',quality:70});
console.log(JSON.stringify({roster,fit,fight,superState,paused,results,errors}));
await browser.close();

